"""Advanced NEURON simulation with custom K+ channel mechanismsThis example shows how to use specific KV12.3 (KCNH8) and KV4.3 (KCND3) mechanisms(requires MOD files or ModelDB mechanisms)Note: KV12.3 (KCNH8/Elk3) is an EAG-family channel, distinct from Kv1.2"""from neuron import h, guifrom neuron.units import ms, mVimport matplotlib.pyplot as pltimport numpy as nph.load_file('stdrun.hoc')class AdvancedNeuronModel:    """    Neuron model with detailed K+ channel mechanisms        This requires specific MOD files for:    - KV12.3 (KCNH8/Elk3) - EAG family, delayed rectifier with slow kinetics    - KV4.3 (KCND3) - Shal family, A-type fast inactivating        Note: KV12.3 is different from Kv1.2:    - KV12.3 = KCNH8 (EAG/Elk family)    - Kv1.2 = KCNA2 (Shaker family)        You can find these in ModelDB (https://modeldb.science/)    Search for KCNH8 or EAG-related channels    """        def __init__(self, name="neuron"):        self.name = name                # Create soma        self.soma = h.Section(name=f'soma_{name}')        self.soma.L = 20        self.soma.diam = 20        self.soma.nseg = 1                # Insert passive properties        self.soma.insert('pas')        self.soma.g_pas = 0.0003  # S/cm2        self.soma.e_pas = -65  # mV                # Insert Na+ current        self.soma.insert('hh')        self.soma.gnabar_hh = 0.12                # Try to insert specific K+ mechanisms        # These names depend on your MOD files        self.has_custom_channels = False        try:            # Attempt to insert KV12.3 (KCNH8/Elk3)            self.soma.insert('kcnh8')  # or 'elk3', 'kv12', etc. depending on MOD file            self.soma.insert('kv4')  # or 'ka', 'kcnd3', etc.            self.has_custom_channels = True            print(f"Custom K+ channels loaded for {name}")        except:            # Fallback to standard HH K+ channels            print(f"Custom channels not found, using HH for {name}")            if 'gkbar_hh' not in dir(self.soma(0.5)):                self.soma.gkbar_hh = 0.036                # Recording vectors        self.v_vec = h.Vector().record(self.soma(0.5)._ref_v)        self.t_vec = h.Vector().record(h._ref_t)                # Record K+ currents if possible        self.ik_vec = h.Vector()        try:            self.ik_vec.record(self.soma(0.5)._ref_ik)        except:            pass                # Stimulus        self.stim = h.IClamp(self.soma(0.5))            def set_kv_conductances(self, kv12_scale=1.0, kv4_scale=1.0):        """        Set K+ channel conductances                Parameters:        -----------        kv12_scale : float            Scaling factor for KV12.3 (KCNH8) conductance (delayed rectifier)        kv4_scale : float            Scaling factor for KV4.3 (KCND3) conductance (A-type)        """        if self.has_custom_channels:            # Adjust specific channel conductances            # Names depend on your MOD file parameter names            try:                self.soma.gkbar_kcnh8 = 0.01 * kv12_scale  # Example value for KV12.3                self.soma.gkbar_kv4 = 0.005 * kv4_scale  # Example value for KV4.3            except:                print("Could not set custom channel conductances")        else:            # Use HH channels as proxy            # Increase gkbar to approximate KV12.3 upregulation            base_gk = 0.036            self.soma.gkbar_hh = base_gk * kv12_scale            print(f"Set gkbar_hh to {self.soma.gkbar_hh:.4f} (scale: {kv12_scale})")                def stimulate(self, delay=5, duration=30, amplitude=0.5):        """Setup current injection"""        self.stim.delay = delay        self.stim.dur = duration        self.stim.amp = amplitude            def run(self, tstop=60):        """Run simulation"""        h.finitialize(-65 * mV)        h.continuerun(tstop * ms)        return np.array(self.t_vec), np.array(self.v_vec)def run_parameter_sweep():    """    Run a parameter sweep to explore effects of different    KV12.3 (KCNH8) and KV4.3 (KCND3) expression levels    """    print("\nRunning parameter sweep...")        # Parameter ranges    kv12_factors = [0.5, 1.0, 1.5, 2.0, 2.5]  # KV12.3 scaling    kv4_factors = [0.3, 0.5, 1.0]  # KV4.3 scaling        results = []        fig, axes = plt.subplots(len(kv4_factors), 1, figsize=(12, 10), sharex=True)    if len(kv4_factors) == 1:        axes = [axes]        for i, kv4_factor in enumerate(kv4_factors):        for kv12_factor in kv12_factors:            neuron = AdvancedNeuronModel(f"kv12_{kv12_factor}_kv4_{kv4_factor}")            neuron.set_kv_conductances(kv12_scale=kv12_factor, kv4_scale=kv4_factor)            neuron.stimulate(delay=5, duration=30, amplitude=0.5)                        t, v = neuron.run(tstop=60)                        # Count spikes            n_spikes = len(np.where(np.diff(np.signbit(v - (-20))))[0]) // 2                        results.append({                'kv12_factor': kv12_factor,                'kv4_factor': kv4_factor,                'n_spikes': n_spikes,                't': t,                'v': v            })                        # Plot            alpha = 0.3 + 0.7 * (kv12_factor - min(kv12_factors)) / (max(kv12_factors) - min(kv12_factors))            axes[i].plot(t, v, linewidth=2, alpha=alpha,                         label=f'KV12.3×{kv12_factor}')                axes[i].set_ylabel('Vm (mV)', fontsize=11)        axes[i].set_title(f'KV4.3 scaled by {kv4_factor}', fontsize=11, fontweight='bold')        axes[i].legend(loc='upper right', fontsize=9)        axes[i].grid(True, alpha=0.3)        axes[i].axhline(y=-20, color='gray', linestyle='--', alpha=0.3)        axes[i].axvspan(5, 35, alpha=0.1, color='green')        axes[-1].set_xlabel('Time (ms)', fontsize=12)    plt.suptitle('K+ Channel Expression Parameter Sweep', fontsize=14, fontweight='bold', y=0.995)    plt.tight_layout()   # plt.savefig('/mnt/user-data/outputs/kv_parameter_sweep.png', dpi=300, bbox_inches='tight')    print("Parameter sweep plot saved")        # Create heatmap of spike counts    fig2, ax = plt.subplots(figsize=(10, 6))        spike_matrix = np.zeros((len(kv4_factors), len(kv12_factors)))    for result in results:        i = kv4_factors.index(result['kv4_factor'])        j = kv12_factors.index(result['kv12_factor'])        spike_matrix[i, j] = result['n_spikes']        im = ax.imshow(spike_matrix, aspect='auto', cmap='viridis', origin='lower')        ax.set_xticks(range(len(kv12_factors)))    ax.set_yticks(range(len(kv4_factors)))    ax.set_xticklabels([f'{f}×' for f in kv12_factors])    ax.set_yticklabels([f'{f}×' for f in kv4_factors])        ax.set_xlabel('KV12.3 Expression Level', fontsize=12)    ax.set_ylabel('KV4.3 Expression Level', fontsize=12)    ax.set_title('Action Potential Count vs K+ Channel Expression', fontsize=13, fontweight='bold')        # Add text annotations    for i in range(len(kv4_factors)):        for j in range(len(kv12_factors)):            text = ax.text(j, i, f'{int(spike_matrix[i, j])}',                          ha="center", va="center", color="white", fontsize=11, fontweight='bold')        cbar = plt.colorbar(im, ax=ax)    cbar.set_label('Number of Spikes', fontsize=11)        plt.tight_layout()    #plt.savefig('/mnt/user-data/outputs/kv_spike_count_heatmap.png', dpi=300, bbox_inches='tight')    print("Spike count heatmap saved")        return resultsdef analyze_repolarization():    """    Analyze how K+ channels affect action potential repolarization    """    print("\nAnalyzing action potential repolarization...")        # Create neurons with different configurations    configs = [        {'name': 'Standard', 'kv12': 1.0, 'kv4': 1.0, 'color': 'blue'},        {'name': 'KV12.3↑', 'kv12': 2.0, 'kv4': 1.0, 'color': 'red'},        {'name': 'KV4.3↓', 'kv12': 1.0, 'kv4': 0.3, 'color': 'green'},        {'name': 'KV12.3↑ + KV4.3↓', 'kv12': 2.0, 'kv4': 0.3, 'color': 'purple'},    ]        fig, axes = plt.subplots(2, 2, figsize=(14, 10))    axes = axes.flatten()        all_traces = []        for config in configs:        neuron = AdvancedNeuronModel(config['name'])        neuron.set_kv_conductances(kv12_scale=config['kv12'], kv4_scale=config['kv4'])                # Brief, strong stimulus to elicit single spike        neuron.stimulate(delay=5, duration=2, amplitude=1.0)        t, v = neuron.run(tstop=40)                all_traces.append({'config': config, 't': t, 'v': v})        # Plot all traces together    for trace in all_traces:        axes[0].plot(trace['t'], trace['v'],                     color=trace['config']['color'],                     linewidth=2.5,                     label=trace['config']['name'])        axes[0].set_xlabel('Time (ms)', fontsize=11)    axes[0].set_ylabel('Membrane Potential (mV)', fontsize=11)    axes[0].set_title('Action Potential Waveforms', fontsize=12, fontweight='bold')    axes[0].legend(fontsize=10)    axes[0].grid(True, alpha=0.3)    axes[0].axvspan(5, 7, alpha=0.1, color='green')        # Zoom on repolarization phase    for trace in all_traces:        axes[1].plot(trace['t'], trace['v'],                     color=trace['config']['color'],                     linewidth=2.5,                     label=trace['config']['name'])        axes[1].set_xlim(6, 20)    axes[1].set_ylim(-80, 40)    axes[1].set_xlabel('Time (ms)', fontsize=11)    axes[1].set_ylabel('Membrane Potential (mV)', fontsize=11)    axes[1].set_title('Repolarization Phase (Zoomed)', fontsize=12, fontweight='bold')    axes[1].grid(True, alpha=0.3)        # Calculate and plot repolarization rates    for idx, trace in enumerate(all_traces):        t, v = trace['t'], trace['v']                # Find peak        peak_idx = np.argmax(v)        peak_t = t[peak_idx]                # Calculate dV/dt during repolarization        repol_indices = np.where((t > peak_t) & (t < peak_t + 10))[0]        if len(repol_indices) > 1:            dv_dt = np.gradient(v[repol_indices], t[repol_indices])                        axes[2].plot(t[repol_indices], dv_dt,                         color=trace['config']['color'],                         linewidth=2.5,                         label=trace['config']['name'])        axes[2].set_xlabel('Time (ms)', fontsize=11)    axes[2].set_ylabel('dV/dt (mV/ms)', fontsize=11)    axes[2].set_title('Repolarization Rate', fontsize=12, fontweight='bold')    axes[2].legend(fontsize=10)    axes[2].grid(True, alpha=0.3)    axes[2].axhline(y=0, color='black', linestyle='-', linewidth=0.5)        # Plot afterhyperpolarization    for trace in all_traces:        t, v = trace['t'], trace['v']        peak_idx = np.argmax(v)        post_spike = np.where(t > t[peak_idx] + 2)[0]                if len(post_spike) > 0:            axes[3].plot(t[post_spike] - t[peak_idx], v[post_spike],                         color=trace['config']['color'],                         linewidth=2.5,                         label=trace['config']['name'])        axes[3].set_xlabel('Time after spike peak (ms)', fontsize=11)    axes[3].set_ylabel('Membrane Potential (mV)', fontsize=11)    axes[3].set_title('Afterhyperpolarization', fontsize=12, fontweight='bold')    axes[3].legend(fontsize=10)    axes[3].grid(True, alpha=0.3)    axes[3].set_xlim(0, 25)        plt.tight_layout()    #plt.savefig('/mnt/user-data/outputs/kv_repolarization_analysis.png', dpi=300, bbox_inches='tight')    print("Repolarization analysis saved")if __name__ == '__main__':    print("=" * 70)    print("Advanced K+ Channel Analysis")    print("=" * 70)        # Run analyses    sweep_results = run_parameter_sweep()    analyze_repolarization()        print("\n" + "=" * 70)    print("Analysis complete!")    print("=" * 70)    print("\nNote: For accurate KV12.3 (KCNH8/Elk3) and KV4.3 (KCND3) modeling,")    print("you'll need specific MOD files. Check ModelDB for:")    print("  - KCNH8/EAG/Elk channels (KV12.3)")    print("  - KCND3/Kv4.x channels (A-type, transient)")    print("\nSuggested ModelDB searches:")    print("  - 'KCNH8' or 'Elk3' for KV12.3")    print("  - 'KCND3' or 'Kv4' for KV4.3")    print("\nIMPORTANT: KV12.3 (KCNH8) ≠ Kv1.2 (KCNA2)")    print("  - KV12.3 = EAG family (slower kinetics)")    print("  - Kv1.2 = Shaker family (faster kinetics)")